import random
from random import choice, randint

def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for x in me if x == 'C')
    my_d = n - my_c

    recent_len = min(8, n)
    recent_op = op[-recent_len:]
    recent_me = me[-recent_len:]
    recent_opp_c = sum(1 for x in recent_op if x == 'C')
    recent_my_c = sum(1 for x in recent_me if x == 'C')

    if n == 1:
        if op[0] == 'D':
            return 'D'
        return 'C'

    # Estimate opponent cooperation rate
    opp_rate = opp_c / n

    # Defect heavily if opponent seems exploitative
    if opp_rate < 0.2:
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # If opponent mostly cooperates, cooperate but be ready to punish
    if opp_rate > 0.8:
        # Check recent defections
        if recent_len >= 4 and recent_opp_c == recent_len and recent_my_c >= recent_len - 1:
            return 'C'
        if recent_opp_c >= recent_len - 1:
            return 'C'
        return 'D' if rng.random() < 0.6 else 'C'

    # Tit-for-tat with forgiveness and occasional exploitation
    last_op = op[-1]
    last_me = me[-1]

    # Detect runs of opponent defections
    run_d = 0
    for x in reversed(op):
        if x == 'D':
            run_d += 1
        else:
            break

    run_c = 0
    for x in reversed(op):
        if x == 'C':
            run_c += 1
        else:
            break

    # Punish long defection runs
    if run_d >= 3:
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    # Against long cooperation, reward and occasionally test
    if run_c >= 4:
        if n > 50 and rng.random() < 0.1:
            return 'D'
        return 'C'

    # Standard reciprocation
    if last_op == 'D':
        # Forgive sometimes
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    else:
        # Sometimes defect to probe
        if rng.random() < 0.06 and n < 90:
            return 'D'
        return 'C'

